                                        SOC_UART_PERIPH_SIGNAL_RX),
                     0);

  esp_configgpio(priv->txpin, OUTPUT);
  esp_gpio_matrix_out(priv->txpin,
                      UART_PERIPH_SIGNAL(priv->id,
                                         SOC_UART_PERIPH_SIGNAL_TX),
                      0, 0);

#ifdef CONFIG_SERIAL_IFLOWCONTROL
  if (priv->iflow)
    {
      uint32_t sig = UART_PERIPH_SIGNAL(priv->id,
                                        SOC_UART_PERIPH_SIGNAL_RTS);

      esp_configgpio(priv->rtspin, OUTPUT);
      esp_gpio_matrix_out(priv->rtspin, sig, 0, 0);
    }

#endif
#ifdef CONFIG_SERIAL_OFLOWCONTROL
  if (priv->oflow)
    {
      uint32_t sig = UART_PERIPH_SIGNAL(priv->id,
                                        SOC_UART_PERIPH_SIGNAL_CTS);

      esp_configgpio(priv->ctspin, INPUT | PULLUP);
      esp_gpio_matrix_in(priv->ctspin, sig, 0);
    }
#endif
}

/****************************************************************************
 * Name: esp_lowputc_restore_pins
 *
 * Description:
 *   Configure both pins back to INPUT mode and detach the TX pin from the
 *   output signal and the RX pin from the input signal.
#include "chip.h"
#include "esp_config.h"
#include "esp_irq.h"
#include "esp_lowputc.h"

#ifdef CONFIG_ESPRESSIF_USBSERIAL
#  include "esp_usbserial.h"
#endif

#include "esp_clk_tree.h"
#include "hal/uart_hal.h"
#include "periph_ctrl.h"
#include "soc/clk_tree_defs.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* The console is enabled and it's not the syslog device, so it should be a
 * serial device.
 */
 *
 * Returned Values:
 *   Zero (OK) is returned.
 *
 ****************************************************************************/

static int esp_setup(uart_dev_t *dev)
{
  struct esp_uart_s *priv = dev->priv;
  uint32_t sclk_freq;

  /* Enable the UART Clock */

  esp_lowputc_enable_sysclk(priv);

  esp_clk_tree_src_get_freq_hz((soc_module_clk_t)UART_SCLK_DEFAULT,
                           ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
                           &sclk_freq);

  /* Initialize UART module */

  uart_hal_init(priv->hal, priv->id);
  uart_hal_set_mode(priv->hal, UART_MODE_UART);
#ifdef CONFIG_ARCH_CHIP_ESP32P4
  PERIPH_RCC_ATOMIC()
    {
      uart_hal_set_sclk(priv->hal, UART_SCLK_DEFAULT);
      uart_hal_set_baudrate(priv->hal, priv->baud, sclk_freq);
    }
#else
  uart_hal_set_sclk(priv->hal, UART_SCLK_DEFAULT);
  uart_hal_set_baudrate(priv->hal, priv->baud, sclk_freq);
#endif
  uart_hal_set_parity(priv->hal, priv->parity);
  set_data_length(priv);
  set_stop_length(priv);
  uart_hal_set_tx_idle_num(priv->hal, 0);

  /* Define 0 as the threshold that means TX FIFO buffer is empty. */

  uart_hal_set_txfifo_empty_thr(priv->hal, 10);

